import { GenericException } from '@game-studio/exceptions';
import { OverlaysEventEmitter } from '@game-studio/overlays';
import { createGameDeepLink, getEnvironment } from '@game-studio/utilities';
import axios from 'axios';
import Vue from 'vue';
import { IAPIConfigResponse, IArcadeBonusCheckResponse, IGameInGameManagerOptions, IGigCategory, IGigConfig, IGigGame, ILobbyResumeReponse, IOpenGameOptions, IOpenGameUrlOptions } from './types';

export class GameInGameManager {
    private static readonly DEBUG_LOAD_TIMEOUT_MS = 8000;

    private options: IGameInGameManagerOptions;
    private iframe: HTMLIFrameElement;
    private bonusSkinName: string;
    private debugLoadTimeout: ReturnType<typeof setTimeout> | null = null;
    private state = Vue.observable({ isEnabledForThisGame: false, isDirectMode: true, activeGame: null as IGigGame | null, categories: [] as IGigCategory[], subGameError: '', isSubGameReady: false });

    public get isEnabledForThisGame() {
        return this.state.isEnabledForThisGame;
    }

    public get isDirectMode() {
        return this.state.isDirectMode;
    }

    public get activeGame() {
        return this.state.activeGame;
    }

    public get categories() {
        return this.state.categories;
    }

    public get subGameError() {
        return this.state.subGameError;
    }

    public get isGameOpen() {
        return !!this.activeGame;
    }

    public get isSubGameReady() {
        return this.state.isSubGameReady;
    }

    public get isDebugMode() {
        return getEnvironment() === 'debug';
    }

    public get games() {
        return this.categories.reduce<IGigGame[]>((games, category) => [...games, ...category.Games], []);
    }

    private normalizeGameIdentifier(identifier: string): string {
        return identifier.trim().toLowerCase();
    }

    private matchesGameIdentifier(game: IGigGame | { Guid: string; InternalName: string; DisplayName?: string }, identifier: string): boolean {
        const normalizedIdentifier = this.normalizeGameIdentifier(identifier);

        return game.Guid.toLowerCase() === normalizedIdentifier
            || this.normalizeGameIdentifier(game.InternalName) === normalizedIdentifier
            || this.normalizeGameIdentifier(game.DisplayName || '') === normalizedIdentifier;
    }

    constructor(options: IGameInGameManagerOptions) {
        this.state.categories = [];
        this.state.activeGame = null;
        this.options = options;
    }

    public setIFrame(iframe: HTMLIFrameElement) {
        this.iframe = iframe;
    }

    public hasGame(gameName: string) {
        try {
            return !!this.getGame(gameName);
        } catch {
            return false;
        }
    }

    public getGame(gameName: string) {
        const game = this.games.find((game) => this.matchesGameIdentifier(game, gameName));

        if (!game) {
            throw new Error(`Game "${gameName}" not found in GiG config`);
        }

        return game;
    }

    public async fetchGames(configName: string = 'gig-config.json', apiEndpoint?: string) {
        this.state.categories = [];

        const gigConfig = await this.loadGigConfig(configName, apiEndpoint);

        if (!gigConfig) {
            return;
        }

        this.state.isDirectMode = !gigConfig.IndirectMode;
        this.state.isEnabledForThisGame = gigConfig.GamesWithGigEnabled.some((game) => game.Guid === this.options.gameGuid);
        this.state.categories = gigConfig.Categories.filter((category) => category.Games.length > 0);
    }

    public async openGame(options: IOpenGameOptions) {
        const { userId, crossCheck, token, gameGuid, domain, useDebugUrl } = options;
        const matchedGame = this.games.find((gigGame) => gigGame.Guid === gameGuid);

        if (!matchedGame) {
            console.error(`Could not find a matching game in GiG config for "${gameGuid}"`);
            return;
        }

        if (domain) {
            this.launchGame(userId, token, matchedGame, crossCheck, domain, useDebugUrl);
            return;
        }

        let hasBonusInAnotherGame: boolean = false;
        let bonusSkinName: string = '';

        let bonusCheckMethod = this.options.bonusCheckMethod;
        if (bonusCheckMethod === undefined) {
            // if method is not passed refer to checkForBonusRounds instead defaulting to true
            // if checkForBonusRounds is true use the api approach else resume
            // this is the behaviour before method was added for backwards compat
            const checkForBonusRounds = this.options.checkForBonusRounds ?? true;
            bonusCheckMethod = checkForBonusRounds ? 'api' : 'lobbyresume';
        }

        if (bonusCheckMethod === 'api') {
            const bonusCheckData = await this.checkForBonusRound(userId, crossCheck);
            bonusSkinName = bonusCheckData.SkinName.toLowerCase();

            if (bonusCheckData && bonusCheckData.HasBonusGameInPlay && !this.matchesGameIdentifier(matchedGame, bonusSkinName)) {
                hasBonusInAnotherGame = true;
            }
        } else if (bonusCheckMethod === 'lobbyresume') {
            const bonusCheckData = await this.checkForBonusRoundLobbyResume(userId, crossCheck);

            if (bonusCheckData && bonusCheckData.InPlayBonusGame && bonusCheckData.InPlayBonusGame.Complete === false && !this.matchesGameIdentifier(matchedGame, bonusCheckData.InPlayBonusGame.SkinName)) {
                bonusSkinName = bonusCheckData.InPlayBonusGame.SkinName.toLowerCase();
                hasBonusInAnotherGame = true;
            }
        }

        this.bonusSkinName = bonusSkinName;

        // Show bonus round popup
        if (hasBonusInAnotherGame) {
            const matchingGame = this.games.find((game) => this.matchesGameIdentifier(game, bonusSkinName));
            const name = matchingGame?.DisplayName || matchingGame?.InternalName || bonusSkinName;
            const isAvailableSubGame = this.games.some((game) => this.matchesGameIdentifier(game, bonusSkinName));
            OverlaysEventEmitter.emit('showBonusInPlay', name, isAvailableSubGame);
        } else {
            // No bonus round in progress, just open the game
            this.launchGame(userId, token, matchedGame, crossCheck, domain, useDebugUrl);
        }
    }

    public async openGameUrl(options: IOpenGameUrlOptions) {
        if (!this.iframe) {
            throw new GenericException('Cannot Open Game-In-Game: IFrame has not been set. Did you call "setIFrame()"');
        }

        if (this.activeGame) {
            this.closeGame();
        }

        this.state.activeGame = this.games[0];

        this.options.gameConnection.createSubGame(this.iframe, options.url, {
            crossCheck: options.crossCheck ?? 0,
            token: options.token,
            userId: options.userId,
            gameId: 'game-in-game'
        });
    }

    public openGameInNewWindow() {
        if (!this.activeGame) {
            throw new GenericException('Cannot Popout Game-In-Game: No Active Game');
        }

        this.options.gameConnection.operator.onUserActionRequired({
            type: 'navigation',
            data: {
                type: 'url',
                location: createGameDeepLink(this.options.host, this.options.apiDomain, this.activeGame.InternalName)
            }
        });
    }

    public resumeBonusRound(userId: string | number, crossCheck: number, token: string) {
        if (this.bonusSkinName === '') {
            return;
        }

        const bonusSkinName = this.bonusSkinName.toLowerCase();
        const matchingSubGame = this.games.find((game) => this.matchesGameIdentifier(game, bonusSkinName));

        if (matchingSubGame) {
            this.launchGame(userId, token, matchingSubGame, crossCheck);
        } else {
            this.options.gameConnection.operator.onUserActionRequired({
                type: 'navigation',
                data: {
                    type: 'url',
                    location: createGameDeepLink(this.options.host, this.options.apiDomain, this.bonusSkinName)
                }
            });
        }

        this.bonusSkinName = '';
    }

    public closeGame() {
        this.clearDebugLoadTimeout();
        this.state.subGameError = '';
        this.state.activeGame = null;
        this.state.isSubGameReady = false;

        if (this.options.gameConnection.subGame) {
            this.options.gameConnection.subGame.disconnect();
        }

        this.iframe.src = '';
    }

    public notifySubGameReady() {
        this.clearDebugLoadTimeout();
        this.state.subGameError = '';
        this.state.isSubGameReady = true;
    }

    public onSubGameError() {
        this.state.isSubGameReady = false;
    }

    private clearDebugLoadTimeout() {
        if (this.debugLoadTimeout !== null) {
            clearTimeout(this.debugLoadTimeout);
            this.debugLoadTimeout = null;
        }
    }

    private startDebugLoadTimeout(url: string) {
        this.clearDebugLoadTimeout();
        this.state.subGameError = '';

        if (!this.isDebugMode) {
            return;
        }

        this.debugLoadTimeout = setTimeout(() => {
            this.state.subGameError = `The game failed to load. Check that the game is running and reachable at:\n${url}`;
        }, GameInGameManager.DEBUG_LOAD_TIMEOUT_MS);
    }

    private launchGame(userId: string | number, token: string, game: IGigGame, crossCheck?: number, domain?: string, useDebugUrl: boolean = false) {
        if (!this.iframe) {
            throw new GenericException('Cannot Open Game-In-Game: IFrame has not been set. Did you call "setIFrame()"');
        }

        if (this.activeGame) {
            if (this.activeGame.Guid !== game.Guid) {
                this.closeGame();
            } else {
                return;
            }
        }

        const url = this.createGameLaunchUrl(game, domain, useDebugUrl);

        this.state.activeGame = game;
        this.state.isSubGameReady = false;

        this.startDebugLoadTimeout(url);

        this.options.gameConnection.createSubGame(this.iframe, url, {
            crossCheck: crossCheck ?? 0,
            token,
            userId,
            gameId: game.Guid
        }).then(() => this.notifySubGameReady());
    }

    private async loadGigConfig(configName: string, apiEndpoint?: string): Promise<IGigConfig | undefined> {
        try {
            const response = await axios.get<IGigConfig>(`${this.options.gigConfigDomain}/${configName}?bust=${Date.now()}`);
            const game = response.data.GamesWithGigEnabled.find((game) => game.Guid === this.options.gameGuid);
            if (!game?.UseApi) { return response.data; }
        } catch (error) {
            if (!apiEndpoint) {
                console.error('Failed to load GiG config.');
                return;
            }
        }

        if (apiEndpoint) {
            return this.loadGigConfigFromApi(apiEndpoint);
        }
    }

    private async loadGigConfigFromApi(apiEndpoint: string): Promise<IGigConfig | undefined> {
        try {
            const response = await axios.get<IAPIConfigResponse>(`${apiEndpoint}`);

            const enabledGamesList = [];
            const isGameInGameEnabled = response.data.featureToggles.some((toggle) => toggle.key === 'EnableGameInGame' && toggle.value);
            if (isGameInGameEnabled) {
                enabledGamesList.push({
                    Guid: response.data.game.guid,
                    InternalName: response.data.game.internalName,
                    DisplayName: response.data.game.displayName,
                });
            }

            const gigConfig = response.data.gigConfig;
            return {
                IndirectMode: gigConfig.indirectMode,
                GamesWithGigEnabled: enabledGamesList,
                Categories: gigConfig.categories.map((category) => ({
                    Guid: category.guid,
                    Name: category.name,
                    Priority: category.priority,
                    Games: category.games.map((game) => {
                        return {
                            Guid: game.guid,
                            InternalName: game.internalName,
                            DisplayName: game.displayName,
                            Mechanic: game.mechanic,
                            LaunchFamily: game.launchFamily,
                            LaunchMode: game.launchMode,
                            Domain: game.domain,
                            LegacyDomain: game.legacyDomain,
                            Path: game.path,
                            LegacyPath: game.legacyPath,
                            Url: game.url,
                            Priority: game.priority,
                            Client: game.client,
                            Label: game.label,
                            RestrictedTo: game.restrictedTo,
                            ExcludedFrom: game.excludedFrom,
                            Features: {
                                canPopout: game.features.canPopout,
                                hasMenu: game.features.hasMenu
                            },
                            Tags: game.tags,
                            Skin: game.skin,
                            LauncherUrl: game.launcherUrl,
                            SplashUrl: game.splashUrl,
                        };
                    })
                }))
            };
        } catch (error) {
            console.error('Failed to load GiG config from API.');
            return undefined;
        }
    }

    private createGameLaunchUrl(game: IGigGame, domain?: string, useDebugUrl: boolean = false): string {
        let url: URL;
        const overrideDomain = domain ?? ((this.isDebugMode && useDebugUrl) ? game.Domain : null);
        if (overrideDomain) {
            const protocol = domain ? 'http' : 'https';
            const host = overrideDomain.replace(/^https?:\/\//i, '');
            url = new URL(`${protocol}://${host}/`);
            url.searchParams.set('game', game.InternalName);
        } else if (game.LaunchMode === 'legacy') {
            const legacyHost = game.LegacyDomain.replace(/^https?:\/\//i, '');
            const legacyPath = game.LegacyPath.startsWith('/') ? game.LegacyPath : `/${game.LegacyPath}`;
            url = new URL(`https://${legacyHost}${legacyPath}`);
        } else {
            url = new URL(game.Url);
        }

        url.searchParams.set('locale', this.options.locale);
        url.searchParams.set('operator', this.options.operator);
        url.searchParams.set('skin', game.Skin);
        url.searchParams.set('parentGame', this.options.gameName);
        url.searchParams.set('shell', this.options.host);

        return url.toString();
    }

    private async checkForBonusRound(userId: string | number, crossCheck?: number) {
        const auth = window.btoa(`${userId}:${crossCheck}`);

        const response = await axios.get<IArcadeBonusCheckResponse>(`${this.options.apiDomain}/api/arcade-resume/bonus-in-play`, {
            headers: {
                'Authorization': `Basic ${auth}`,
                'X-Tombola-Deviceidentifier': this.options.device.deviceID,
                'X-Tombola-Devicetype': this.options.device.type.value,
            }
        });

        return response.data;
    }

    private async checkForBonusRoundLobbyResume(userId: string | number, crossCheck?: number) {
        const environment = getEnvironment();
        let env = environment === 'live' ? '' : `${environment}-`;
        if (environment === 'debug') { env = 'dev-'; }
        const domainSuffix = this.options.locale.split('-')[0];

        const url = `https://${env}arcade.tombola.${domainSuffix}/lobby/resume`;

        const body = {
            CrossCheck: crossCheck,
            UserId: userId,
            RequestType: 'Resume',
            ClientTypeId: this.options.device.typeCode
        };

        const response = await axios.post<ILobbyResumeReponse>(url, body);

        return response.data;
    }
}